export const getGetItemPriceHistoryUrl = (itemType: 'card' | 'sealed_product',
    itemId: number,
    params?: GetItemPriceHistoryParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/market/price-history/${itemType}/${itemId}?${stringifiedParams}` : `/api/market/price-history/${itemType}/${itemId}`
}

